package com.bts.viewplustest.user;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/me") public class ProfileController { private final UserRepository users; private final PasswordEncoder passwords; public ProfileController(UserRepository u,PasswordEncoder p){users=u;passwords=p;} @GetMapping public Profile get(Authentication a){return response(user(a));} @PatchMapping public Profile update(Authentication a,@Valid @RequestBody Update q){User u=user(a);if(q.nickname()!=null&&!q.nickname().isBlank())u.changeNickname(q.nickname().trim());if(q.newPassword()!=null&&!q.newPassword().isBlank()){if(q.currentPassword()==null||!passwords.matches(q.currentPassword(),u.getPasswordHash()))throw new IllegalArgumentException("현재 비밀번호가 올바르지 않습니다.");u.changePasswordHash(passwords.encode(q.newPassword()));}return response(users.save(u));} private User user(Authentication a){return users.findById((Long)a.getPrincipal()).orElseThrow();} private Profile response(User u){return new Profile(u.getId(),u.getEmail(),u.getNickname());} public record Update(@Size(min=2,max=30) String nickname,@Size(min=8,max=72) String newPassword, String currentPassword){} public record Profile(Long id,String email,String nickname){} }
